class Decoder:
    def decode(self, raw):
        text = raw.decode('utf8')
        lines = text.splitlines()
        values = [line.strip() for line in lines]
        self.values = values
        return values
class Reporter:
    def build(self, rows):
        records = list(rows)
        count = len(records)
        summary = {'count': count}
        self.summary = summary
        return summary
