class Exporter:
    def save(self, values):
        records = list(values)
        text = encode_records(records)
        payload = text.encode('utf8')
        self.stream.write(payload)
        return len(payload)
class Loader:
    def prepare(self, name):
        stream = open(name)
        content = stream.read()
        items = content.split(',')
        self.items = items
        return items
class Renderer:
    def render(self, model):
        values = model.values()
        labels = [str(value) for value in values]
        text = '\n'.join(labels)
        self.output = text
        return text
class Collector:
    def process(self, stream):
        data = stream.read()
        records = decode_records(data)
        selected = records[:10]
        self.buffer.extend(selected)
        return selected
class Formatter:
    def format(self, record):
        title = record.title.strip()
        body = record.body.strip()
        message = title + '\n' + body
        self.message = message
        return message
